-- changeset ?:1792454400000-1
CREATE TABLE "imports" (
    "id"         INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    UUID        NOT NULL,
    "account"    INTEGER     NOT NULL,
    "file_name"  TEXT        NOT NULL,
    "row_count"  INTEGER     NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "imports_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "imports_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
    CONSTRAINT "imports_account_fkey" FOREIGN KEY ("account") REFERENCES "accounts" ("id") ON DELETE CASCADE
);

-- changeset ?:1792454400000-2
CREATE INDEX "imports_user_id_idx" ON "imports" ("user_id");

-- changeset ?:1792454400000-3
ALTER TABLE "transactions" ADD COLUMN "import_id" INTEGER;
ALTER TABLE "transactions"
    ADD CONSTRAINT "transactions_import_id_fkey"
        FOREIGN KEY ("import_id") REFERENCES "imports" ("id") ON DELETE SET NULL;
CREATE INDEX "transactions_import_id_idx" ON "transactions" ("import_id");

-- changeset ?:1792454400000-4
CREATE TABLE "import_fingerprints" (
    "user_id"        UUID    NOT NULL,
    "account"        INTEGER NOT NULL,
    "fingerprint"    TEXT    NOT NULL,
    "transaction_id" INTEGER NOT NULL,
    "import_id"      INTEGER NOT NULL,
    CONSTRAINT "import_fingerprints_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_fingerprints_account_fkey" FOREIGN KEY ("account") REFERENCES "accounts" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_fingerprints_transaction_id_fkey" FOREIGN KEY ("transaction_id") REFERENCES "transactions" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_fingerprints_import_id_fkey" FOREIGN KEY ("import_id") REFERENCES "imports" ("id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX "import_fingerprints_unique_idx" ON "import_fingerprints" ("user_id", "account", "fingerprint");
CREATE INDEX "import_fingerprints_transaction_id_idx" ON "import_fingerprints" ("transaction_id");

-- changeset ?:1792454400000-5
CREATE TABLE "import_merges" (
    "transaction_id"             INTEGER NOT NULL,
    "import_id"                  INTEGER NOT NULL,
    "previous_sender"            INTEGER,
    "previous_receiver"          INTEGER,
    "previous_amount"            INTEGER NOT NULL,
    "previous_currency"          INTEGER NOT NULL,
    "previous_receiver_amount"   INTEGER NOT NULL,
    "previous_receiver_currency" INTEGER NOT NULL,
    "previous_category"          INTEGER,
    CONSTRAINT "import_merges_pkey" PRIMARY KEY ("transaction_id"),
    CONSTRAINT "import_merges_transaction_id_fkey" FOREIGN KEY ("transaction_id") REFERENCES "transactions" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_merges_import_id_fkey" FOREIGN KEY ("import_id") REFERENCES "imports" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_merges_previous_sender_fkey" FOREIGN KEY ("previous_sender") REFERENCES "accounts" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_merges_previous_receiver_fkey" FOREIGN KEY ("previous_receiver") REFERENCES "accounts" ("id") ON DELETE CASCADE,
    CONSTRAINT "import_merges_previous_category_fkey" FOREIGN KEY ("previous_category") REFERENCES "categories" ("id") ON DELETE CASCADE
);
CREATE INDEX "import_merges_import_id_idx" ON "import_merges" ("import_id");

